INSERT INTO `klever_tyres_chat` VALUES (1,'cmv0tx3hr001wnrdeol6wofyo','BrandPreference','Do you have a specific brand in mind, or are you looking for options within a particular budget? I’d be happy to find the perfect match for you! 😊','car_tyres',NULL,NULL,1,2,'2026-07-16 15:38:14.000','2026-07-22 12:17:56.000'),(2,'cmv0tx3hr001wnrdeol6wofyo','Carmake','Sure! I’d be happy to help. Can you please share your vehicle make, model, and year?','car_tyres',NULL,NULL,1,5,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(3,'cmv0tx3hr001wnrdeol6wofyo','Installationsupport','We provides Free fitment at our garage partner for a quick fit or Home (doorstep) installation at additional cost AED 300.00 via Mobile Van.','car_services',NULL,4,1,3,'2026-07-16 15:38:14.000','2026-07-22 12:17:56.000'),(4,'cmv0tx3hr001wnrdeol6wofyo','Stockcheck','Kindly allow me a moment to confirm the stock.','car_tyres',NULL,NULL,1,6,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(5,'cmv0tx3hr001wnrdeol6wofyo','Payment Options Available','At TyresCart.ae, we accept Credit/Debit Card and Tamara / Tabby Pay in Installment options till 12 months. Let me know if you’d like help checking out.','other',NULL,4,1,20,'2026-07-16 15:38:14.000','2026-07-19 20:15:18.000'),(6,'cmv0tx3hr001wnrdeol6wofyo','Orderconfirm','We’ve received your order at TyresCart.ae and would like to confirm it with you. Then, we will verify the physical stock in our warehouse and provide you with an update accordingly.','car_tyres',NULL,NULL,1,3,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(7,'cmv0tx3hr001wnrdeol6wofyo','Location','May I kindly ask for your location and area in the UAE to assist you better?','car_tyres',NULL,NULL,1,7,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(8,'cmv0tx3hr001wnrdeol6wofyo','Closinghours','Due to closing hours, we’re unable to physically verify the stock. May I update you tomorrow morning?','car_tyres',NULL,NULL,1,8,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(9,'cmv0tx3hr001wnrdeol6wofyo','followup first time','Hello 👋, I just wanted to follow up regarding your earlier inquiry.','car_tyres',NULL,6,1,9,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(10,'cmv0tx3hr001wnrdeol6wofyo','Discountpayment','May I know how you plan to make the payment? I’ll check if any discount can be applied based on the method.','car_tyres',NULL,NULL,1,10,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(11,'cmv0tx3hr001wnrdeol6wofyo','Onlinestore','We TyresCart.ae is a trusted online tyre shop in the UAE, offering a wide range of premium tyres, wheels, car batteries, and automotive care solutions. We provide convenient online ordering, competitive prices, and professional installation through our partner network across Abu Dhabi, Dubai, and other Emirates.','car_services',NULL,NULL,1,11,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(12,'cmv0tx3hr001wnrdeol6wofyo','Wheelalignment','Wheel alignment check is free of charge. However, if any adjustments are needed, the fixing charges will depend on the alignment report and Usually, the cost of wheel alignment services starts from AED 150+','car_services',NULL,NULL,1,12,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(13,'cmv0tx3hr001wnrdeol6wofyo','Tyresize','Kindly share your current tyre size if you know it, or send us a photo of the tyre sidewall so we can assist you better.','car_tyres',NULL,NULL,1,13,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(14,'cmv0tx3hr001wnrdeol6wofyo','paymentpreference','After completing the payment, please send us a screenshot so our accounts team can verify and update your order.','car_tyres',NULL,NULL,1,14,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(15,'cmv0tx3hr001wnrdeol6wofyo','tyresqty','May I know how many tyres you are looking to purchase?','car_tyres',NULL,NULL,1,15,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(16,'cmv0tx3hr001wnrdeol6wofyo','choicefinal','Please let us know once you finalize your choice, so we can proceed accordingly.','car_tyres',NULL,NULL,1,16,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(17,'cmv0tx3hr001wnrdeol6wofyo','quickorder','You can make payment from https://www.tyrescart.ae/quick-order-payment/','car_tyres',NULL,NULL,1,17,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(18,'cmv0tx3hr001wnrdeol6wofyo','Incomplete Order','Looks like you started an order with Online Payment at TyresCart.ae but didn’t finish it. Need any assistance? We\'re here to help!','car_tyres',NULL,6,1,18,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(19,'cmv0tx3hr001wnrdeol6wofyo','referring','Thank you for choosing TyresCart.ae for your recent order. We’d truly appreciate your support by referring our online shop TyresCart.ae 🇦🇪 to your family, friends, or colleagues. Your recommendation means a lot to us 🤗','car_tyres',NULL,NULL,1,19,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(20,'cmv0tx3hr001wnrdeol6wofyo','Car Insurance Process','To proceed with your insurance quote, please share your *Driving License*, *Mulkiya*, and *Emirates ID*. This helps us get the best and most accurate offers for you.','car_insurance',NULL,6,1,20,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(21,'cmv0tx3hr001wnrdeol6wofyo','confirmtyresize','To confirm the tyre size selected in your order, we kindly request you to share clear photos of the tyre sidewall. This will help us verify the size and arrange the correct tyres for you.','car_tyres',NULL,NULL,1,21,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(22,'cmv0tx3hr001wnrdeol6wofyo','Leave Customer Cross Sale Approach Service','\"Also, just to let you know ?\n\nAt TyresCart.ae: We’re more than just tyres — we’ve got your car covered with:\n\n?️ Affordable car insurance - (Comprehensive & Third Party)\n? Fast battery replacement & emergency jump start\n? Brake pad replacement for safer driving\n?️ Essential car services under one roof\n? Stylish rims & wheels to upgrade your ride\n\n? Need help anytime? Just drop us a message — happy to assist ?\"','other',NULL,6,1,22,'2026-07-16 15:38:14.000','2026-07-22 12:17:56.000'),(23,'cmv0tx3hr001wnrdeol6wofyo','fitting','We hope everything went smoothly. Was the fitting done well?','car_services',NULL,NULL,1,23,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(24,'cmv0tx3hr001wnrdeol6wofyo','Transparency','At TyresCart.ae, Transparency is our foundation. We focus on building lasting relationships through reliable service and constant support, ensuring our clients always trust us first with their vehicles. 😊','car_tyres',NULL,NULL,1,24,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(25,'cmv0tx3hr001wnrdeol6wofyo','alternate','At TyresCart.ae, Transparency is our foundation. We focus on building lasting relationships through reliable service and constant support, ensuring our clients always trust us first with their vehicles. 😊','car_tyres',NULL,NULL,1,1,'2026-07-16 15:38:14.000','2026-07-29 10:11:55.000'),(26,'cmv0tx3hr001wnrdeol6wofyo','readyorder','Please share the below details to ready order and invoice Name Phone EMail Car Plate Number Car Make Car Model Car Year','car_tyres',NULL,NULL,1,26,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(27,'cmv0tx3hr001wnrdeol6wofyo','completeinstalltion','We trust that your tire fitting service was completed to your satisfaction. Should you require any assistance during your journey, please don’t hesitate to contact us. Your safety and satisfaction are our top priorities. 🚘😊','car_services',NULL,NULL,1,27,'2026-07-16 15:38:14.000','2026-07-19 16:54:16.000'),(28,'cmv0tx3hr001wnrdeol6wofyo','invoice','Invoice in the Name -\n*Trade Name:* DSP Trade Hub FZ-LLC\n*Address:* FDAM0707, Compass Building, Al Shohada Road, AL Hamra Industrial Zone-FZ, Ras Al Khaimah, 1624, Ras Al Khaimah +971505069575\n*TRN:* 105036835400003','car_tyres',NULL,NULL,1,28,'2026-07-16 15:38:14.000','2026-07-22 12:17:56.000'),(29,'cmv0tx3hr001wnrdeol6wofyo','offline','Thanks for reaching out! We received your contact information via our website TyresCart.ae.','car_tyres',NULL,6,1,29,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(30,'cmv0tx3hr001wnrdeol6wofyo','greetings','Hi there! Welcome to TyresCart.ae. How can we help you with your inquiry today?','car_tyres',NULL,6,1,30,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(31,'cmv0tx3hr001wnrdeol6wofyo','tyrehelp','Looking for tyres? We offer a wide range of brands and sizes. Please share your car details or tyre size to help you better.','car_tyres',NULL,NULL,1,31,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(32,'cmv0tx3hr001wnrdeol6wofyo','delivery','We offer same-day or next-day delivery within Abu Dhabi & Dubai 🚚. Free installation is available at our partner locations','car_services',NULL,NULL,1,32,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(33,'cmv0tx3hr001wnrdeol6wofyo','nostock','This item is currently out of stock. Would you like us to notify you once it\'s available or suggest an alternative?','car_tyres',NULL,NULL,1,33,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(34,'cmv0tx3hr001wnrdeol6wofyo','paymentconfirm','We’ve received your payment. Thank you! Your order is being processed and you’ll receive a confirmation email shortly.','car_tyres',NULL,NULL,1,34,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(35,'cmv0tx3hr001wnrdeol6wofyo','feedback','We’d love to hear your feedback. Please rate your experience when you have a minute 😊','car_tyres',NULL,NULL,1,35,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(36,'cmv0tx3hr001wnrdeol6wofyo','stockreserve','To reserve the stock, we kindly request you to make the payment online via link. This will allow us to arrange the tyres at our installer partner based on the available appointment time.','car_services',NULL,NULL,1,36,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(37,'cmv0tx3hr001wnrdeol6wofyo','done','May I know if the tyre installation has been completed?','car_services',NULL,NULL,1,37,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(38,'cmv0tx3hr001wnrdeol6wofyo','stockcheck2','Once stock confirmed, we’ll send you the payment link to secure your order.','car_tyres',NULL,NULL,1,38,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(39,'cmv0tx3hr001wnrdeol6wofyo','pricegaurantee','We always aim to provide the best possible price guarantee for our customers.','car_tyres',NULL,NULL,1,39,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(40,'cmv0tx3hr001wnrdeol6wofyo','forward','Thanks! We’ve passed your information to the concerned department — they’ll be in touch with you soon through WhatsApp or a call.','car_tyres',NULL,NULL,1,40,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(41,'cmv0tx3hr001wnrdeol6wofyo','understand','We hope you understand the process. Please feel free to contact us anytime if you have any questions.','car_tyres',NULL,NULL,1,41,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(42,'cmv0tx3hr001wnrdeol6wofyo','tyrepreference','Kindly review your preferred brand, and we’ll check the stock availability accordingly.','car_tyres',NULL,NULL,1,42,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(43,'cmv0tx3hr001wnrdeol6wofyo','discounttyre','We’ll check the stock and do our best to give you the most competitive offer.','car_tyres',NULL,NULL,1,43,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(44,'cmv0tx3hr001wnrdeol6wofyo','googlepreview','Enjoyed your purchase at TyresCart.ae? 😊 We\'d love to hear your feedback — leave us a quick Google review here: https://g.page/r/CQ_gDJtAoV1oEAI/review','car_tyres',NULL,NULL,1,44,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(45,'cmv0tx3hr001wnrdeol6wofyo','experience','Hope your online purchase went smoothly! 😊 How was your experience with the fitting at our installer partner? We’d really appreciate your feedback as part of our internal review to help us improve.','car_services',NULL,NULL,1,45,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(46,'cmv0tx3hr001wnrdeol6wofyo','yearpreference','Would you like tyres from the 2025 or 2026 manufacturing year?','car_tyres',NULL,NULL,1,46,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(47,'cmv0tx3hr001wnrdeol6wofyo','expirepaymentlink','Please note: the payment link will expire within 15 minutes from the time it is generated.','car_tyres',NULL,NULL,1,47,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(48,'cmv0tx3hr001wnrdeol6wofyo','tyrescart','TyresCart.ae are an independent online business working with multiple suppliers, which allows us to offer a wide range of options based on your preferences. We\'re here to support you throughout your entire journey with us.','car_tyres',NULL,NULL,1,48,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(49,'cmv0tx3hr001wnrdeol6wofyo','currentbrand','Could you please let us know which brand is currently in your car?','car_tyres',NULL,NULL,1,49,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(50,'cmv0tx3hr001wnrdeol6wofyo','thanks','Thank you for your business! We look forward to working with you again.','car_tyres',NULL,NULL,1,50,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(51,'cmv0tx3hr001wnrdeol6wofyo','reserve','To confirm and reserve the tyres, we kindly request you to make the payment online. Once the payment is received, we will prepare the tyres at the warehouse and arrange them at the installation location.','car_services',NULL,NULL,1,51,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(52,'cmv0tx3hr001wnrdeol6wofyo','Welcome TyresCart.ae Customer','Welcome to TyresCart.ae! 🚗\n\nWe\'re more than just tyres — we\'ve got your car covered with:\n\n🛞 Car Tyres from all major brands\n🛡️ Car Insurance (Third-Party & Comprehensive)\n🔋 Battery Replacement & Emergency Service\n🛠️ Brake Pad Replacement & Service\n⚙️ Essential Quick Car Services (Oil, AC, etc.)\n\n💬 Need help anytime? Just drop us a message — we\'re happy to assist! 😊','other',NULL,6,1,52,'2026-07-16 15:38:15.000','2026-10-12 12:42:24.094'),(53,'cmv0tx3hr001wnrdeol6wofyo','reviewprice','We would like to review competitor pricing structures to ensure our customers receive the best possible prices from the same brand agencies. This will also help us communicate effectively with our partners regarding our cost expectations.','car_tyres',NULL,NULL,1,53,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(54,'cmv0tx3hr001wnrdeol6wofyo','acknowledgeinstaller','Please share this document with the installer for their acknowledgement. Once confirmed, they can proceed with initiating your tyre fitting appointment.','car_services',NULL,NULL,1,54,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(55,'cmv0tx3hr001wnrdeol6wofyo','installerlocation','We have tire fitting installer in every Emirate across the UAE, so you can always find a professional to fit your tires nearby.','car_services',NULL,NULL,1,55,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(56,'cmv0tx3hr001wnrdeol6wofyo','qualityproducts','TyresCart.ae is committed to providing high-quality products and full support for our customers until it\'s time for their next set of tires.','car_tyres',NULL,NULL,1,56,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(57,'cmv0tx3hr001wnrdeol6wofyo','opportunity','Give us the opportunity to serve you; we promise to provide expert care and value for as long as you are on the road with our tires. 🤗','car_tyres',NULL,NULL,1,57,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(58,'cmv0tx3hr001wnrdeol6wofyo','quickordercard','You can make payment from https://www.tyrescart.ae/quick-order-payment-card/','car_tyres',NULL,NULL,1,58,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(59,'cmv0tx3hr001wnrdeol6wofyo','appointmentcustomer','We will send over your Work Order Appointment copy soon. Please present this to the installer when you arrive to ensure a smooth and quick installation process.','car_services',NULL,NULL,1,59,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(60,'cmv0tx3hr001wnrdeol6wofyo','clearimage','Also please share a clear image of current tyres where tyre size is mentioned, this helps us to double verify the ordered size is correct','car_tyres',NULL,NULL,1,60,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(61,'cmv0tx3hr001wnrdeol6wofyo','VAT','Trade Name: DSP Trade Hub FZ-LLC TRN: 105036835400003','car_tyres',NULL,NULL,1,61,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(62,'cmv0tx3hr001wnrdeol6wofyo','reviews','Dear Valued Customer,\n\nThank you for choosing TyresCart.ae for your recent tyre purchase. Our goal is to provide a seamless \'click-to-fit\' experience, and your feedback is essential in helping us maintain that standard.\n\nWe have recently launched our official Trustpilot page and would be honored if you could take a moment to share your experience with us. Your review helps other drivers in the UAE make informed decisions.\n\nShare your feedback here: https://www.trustpilot.com/review/tyrescart.ae\n\nThank you for being a part of our journey!','car_tyres',NULL,NULL,1,62,'2026-07-16 15:38:15.000','2026-07-22 12:17:56.000'),(63,'cmv0tx3hr001wnrdeol6wofyo','review','Thank you for choosing TyresCart.ae for your recent tyre purchase. Our goal is to provide a seamless \'click-to-fit\' experience, and your feedback is essential in helping us maintain that standard.\n\nWe have recently launched our official Trustpilot page and would be honored if you could take a moment to share your experience with us. Your review helps other drivers in the UAE make informed decisions.\n\nShare your feedback here: https://www.trustpilot.com/review/tyrescart.ae\n\nThank you for being a part of our journey!','car_tyres',NULL,NULL,1,63,'2026-07-16 15:38:15.000','2026-07-22 12:17:56.000'),(64,'cmv0tx3hr001wnrdeol6wofyo','Insurance Documents','As per the *Central Bank of the UAE (CBUAE)* guidelines, we are not permitted to collect documents such as a driving license, Emirates ID, or vehicle registration copy, nor can we accept confirmations through WhatsApp or any instant messaging application.\n\nKindly share the required documents via email to the address provided below.\ninfo@tyrescart.ae','car_insurance',NULL,6,1,64,'2026-07-16 15:38:15.000','2026-07-22 12:17:56.000'),(65,'cmv0tx3hr001wnrdeol6wofyo','googlemappreview','If you have a moment, please leave us a Google review at this link: https://maps.app.goo.gl/wY8wmukb8K8e63E39 Your feedback means a lot to our team. Safe driving! 🚘','car_tyres',NULL,NULL,1,65,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(66,'cmv0tx3hr001wnrdeol6wofyo','Insurance Quote','Just to let you know ?\n\nAt TyresCart.ae: We’ve got your car covered with more than just tyres! ?️\n\nGet *reliable and affordable car insurance* tailored for your needs:\n\n✅ Comprehensive Insurance – Full protection for total peace of mind.\n\n✅ Third-Party Liability – Essential coverage at the best rates.\n\n?  Need a quick quote? Just drop us a message — Happy to assist ?','car_insurance',NULL,6,1,66,'2026-07-16 15:38:15.000','2026-07-22 12:17:56.000'),(67,'cmv0tx3hr001wnrdeol6wofyo','No Tabby/Tamara Payment Option','For selected premium tyres on the website, the Tabby/Tamara payment option has been disabled to maintain competitive pricing for customers. Customers will normally see only the standard card payment option at checkout.','other',NULL,6,1,67,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(68,'cmv0tx3hr001wnrdeol6wofyo','otherprice','May I know where you sourced this specific pricing? We are actively expanding our vendor network to improve stock availability and ensure we always deliver the most competitive rates to our end customers. 😊','car_tyres',NULL,NULL,1,68,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(69,'cmv0tx3hr001wnrdeol6wofyo','otherprice2','This allows us to be significantly more competitive in the market and pass the direct financial benefits straight to our customers. 📈','car_tyres',NULL,NULL,1,69,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(70,'cmv0tx3hr001wnrdeol6wofyo','Got Deal from Other','Glad you got a great deal! Keep us in mind for your future car/bike tyre or battery or insurance needs, and we’ll make sure to take excellent care of you with our best service and rates. 👍','other',NULL,6,1,70,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(71,'cmv0tx3hr001wnrdeol6wofyo','updatestatusorder','Please confirm once the tire fitting service has been successfully completed. This will allow us to update the order status in our system and officially close the file 🤗','car_services',NULL,NULL,1,71,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(72,'cmv0tx3hr001wnrdeol6wofyo','cardpaymentlink','You can make the Payment Online at https://qr.totalpay.ae/202509043268b96dcc10555','car_tyres',NULL,NULL,1,72,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(73,'cmv0tx3hr001wnrdeol6wofyo','Payment Advance','We require an advance payment to process the order. Once confirmed, we\'ll reserve the tyres and have them ready at the installer location for your scheduled fitment.','car_services',NULL,6,1,73,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(74,'cmv0tx3hr001wnrdeol6wofyo','klever','Just to let you know, Klever.ae our parent company also specializes in Software IT and Digital Marketing right here in the UAE. We would be more than happy to assist you with any technology or marketing needs you might have. 🤗','other',NULL,1,1,74,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(75,'cmv0tx3hr001wnrdeol6wofyo','Tabby/Tamara Payment Option','Fyi, Due to narrow margins on certain items, we are normally unable to offer *Tabby/Tamara installment* plans. However, if you would prefer to pay in installments, we can arrange it by applying a additional 5% processing fee to the total amount.','other',NULL,6,1,75,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(76,'cmv0tx3hr001wnrdeol6wofyo','Renew Car Insurance','As you prepare for your upcoming vehicle renewal, please let us know if you need assistance with Car Insurance. We provide excellent options for both Full Comprehensive and Third-Party coverage, and we can generate a quick quote for you today.','car_insurance',NULL,6,1,76,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(77,'cmv0tx3hr001wnrdeol6wofyo','Prepare Order','Once payment done successfully, please share the below details to ready order and invoice Name Phone Email Car Plate Number Car Make Car Model Car Year','car_tyres',NULL,6,1,77,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(78,'cmv0tx3hr001wnrdeol6wofyo','Alternate Brand Choice','Are you open to alternative brands that offer the same high quality and fall within the same price range?','car_tyres',NULL,6,1,78,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(79,'cmv0tx3hr001wnrdeol6wofyo','Order Online','At TyresCart.ae, we operate as an online retailer partnered with certified fitting centers across the UAE. To secure your order, simply complete your payment online; we will immediately reserve your tyres and schedule your fitting appointment at a time and location most convenient for you! 😊','car_services',NULL,6,1,79,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(80,'cmv0tx3hr001wnrdeol6wofyo','followup second time','Just following up to see if you are still looking for tyres for your vehicle? If you have any questions about brands, availability, or pricing, please let me know. I’m here to help you get the best deal! 😊','car_tyres',NULL,6,1,80,'2026-07-16 15:38:15.000','2026-07-19 16:54:16.000'),(81,'cmv0tx3hr001wnrdeol6wofyo','Hours','We\'re currently open\nOur business hours are:\nThursday: 09:00 - 18:00\nFriday: 09:00 - 18:00\nSaturday: 09:00 - 18:00\nSunday: Closed\nMonday: 09:00 - 18:00\nTuesday: 09:00 - 18:00\nWednesday: 09:00 - 18:00','car_tyres',NULL,NULL,1,81,'2026-07-16 15:38:15.000','2026-07-22 12:17:56.000'),(82,'cmv0tx3hr001wnrdeol6wofyo','Price Includes','Fully Fitted Price per tyre\n\nThere are NO EXTRAS to pay on the day of your visit - in relation to the tyre fitting.\n\nThe following is included in the price,\n\nVAT\nFitting (Bead lock wheel etc. excluded)\nBalancing\nNew rubber valve (standard valve only)\nDelivery to installer\nDisposal of old tyres\nOn purchase of 4 tyres, scheduled instance of 1 FREE tyre rotation every 20,000 kms per year\n\nNote: Wheel Alignment is not included','car_services',NULL,6,1,82,'2026-07-16 15:38:15.000','2026-07-22 12:17:56.000'),(83,'cmv0tx3hr001wnrdeol6wofyo','Car Battery Request','TyresCart.ae would be happy to help you find the perfect battery for your vehicle! To ensure we check the exact compatibility, stock availability, and give you the best pricing, could you kindly share a few details with us?\n\n? Car Make & Model: (e.g., Nissan Patrol, Toyota Camry)\n? Year of Manufacture: (e.g., 2021)\n? Current Battery Model: Share current existing battery pics or model number\n\nOnce you share these, we’ll send over the best options right away! ?','battery',6,6,1,83,'2026-07-18 10:49:06.000','2026-07-22 12:17:56.000'),(84,'cmv0tx3hr001wnrdeol6wofyo','klevertest','This description is klever test add data ','other',NULL,NULL,1,100,NULL,NULL),(1408,'cmv6keg6b00cenrc2bvsq0q64','greetings','Hi there! Welcome to TyresCart.ae.','car_tyres',NULL,NULL,1,30,NULL,'2026-10-13 10:55:26.062'),(1409,'cmv6keg6b00cenrc2bvsq0q64','tyrescart','TyresCart.ae are an independent online business.','car_tyres',NULL,NULL,1,48,NULL,'2026-10-13 10:55:26.062'),(1410,'cmv6keg6b00cenrc2bvsq0q64','Stockcheck','Kindly allow me a moment to confirm the stock.','car_tyres',NULL,NULL,1,6,NULL,'2026-10-13 10:55:26.062'),(1411,'cmv6keg6b00cenrc2bvsq0q64','Wheelalignment','Alignment check is free; fixing starts from AED 150+','car_services',NULL,NULL,1,12,NULL,'2026-10-13 10:55:26.062'),(1412,'cmv6keg6b00cenrc2bvsq0q64','Insurance Quote','Comprehensive or third party: 100% covered_','car_insurance',NULL,NULL,1,66,NULL,'2026-10-13 10:55:26.062'),(1413,'cmv6keg6b00cenrc2bvsq0q64','tyrescart-old','Disabled duplicate','other',NULL,NULL,0,1,NULL,'2026-10-13 10:55:26.062'),(1414,'cmv6keg6b00cenrc2bvsq0q64','mytyrescartlink','Order at the shop','other',NULL,NULL,1,5,NULL,'2026-10-13 10:55:26.062'),(1415,'cmv6ke1s40005nrc2ekp5qxz3','tyrescart','B only','other',NULL,NULL,1,0,NULL,'2026-10-13 10:55:26.064'),(1416,'cmv6kegeq00d3nrc2qv0ptuj9','Welcome TyresCart.ae Customer','Welcome to TyresCart.ae \n\nWe’re more than just Tyres — we’ve got your car covered with:\n\n? Car Tyres having all major Brands \n?️ Car Insurance (3rd Party & Comprehensive)\n? Battery Replacement & Emergency Service\n? Brake Pad Replacement & Service\n?️ Essential Quick Car Services (Oil/AC/etc)\n\n? Need help anytime? Just drop us a message — Happy to assist ?','other',NULL,6,1,52,'2026-07-16 15:38:15.000','2026-07-22 12:17:56.000'),(1417,'cmv6kegeq00d3nrc2qv0ptuj9','Welcome restored','Welcome to TyresCart.ae \n\nWe’re more than just Tyres — we’ve got your car covered with:\n\n🚗 Car Tyres having all major Brands \n🛡️ Car Insurance (3rd Party & Comprehensive)\n🚗 Battery Replacement & Emergency Service\n🚗 Brake Pad Replacement & Service\n🛡️ Essential Quick Car Services (Oil/AC/etc)\n\n🚗 Need help anytime? Just drop us a message — Happy to assist 😊','other',NULL,6,1,52,'2026-07-16 15:38:15.000','2026-07-22 12:17:56.000');
